{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "The **20% cap—AUD 4.8 million—is not automatically unacceptable**, but must be assessed with the other restrictions"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "reducing the AUD 25,000 de minimis and AUD 250,000 basket"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "seeking a longer general warranty notification period, for example 24 months"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Reject “administrative simplicity” as a reason to give title and capacity the general regime."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Require express, consistent carve-outs across every relevant clause"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Require fair disclosure with sufficient detail to identify the nature and scope of the matter."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "The exclusion for anything “discoverable” by the Buyer or its advisers should be rejected."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make effective Bluefen change-of-control consent a condition precedent, waivable only by the Buyer."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Arrange repayment through the Completion funds flow and effective release of all relevant security and guarantees at Completion."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Allocate the agreed Seller-borne cost through a price deduction, funded payment or other enforceable mechanism."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Broaden the specific indemnity beyond the SOW3 payment to resulting title defects, infringement claims and reasonable cure, defence and replacement costs"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Require proportionate investigation and remediation before Completion, with Buyer visibility and cooperation."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Review the three renewals together, including service periods, commercial necessity, cancellation rights and whether they duplicate existing services."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Reject blanket all-claims limitations, constructive knowledge and indiscriminate disclosure; separate fundamental, tax and specific indemnity regimes."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012 supports the registered holding but is not complete verification of good, unencumbered title."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Require a standalone pre-Completion tax indemnity, suitable tax warranties and a tax-specific liability regime."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

